class Queue {

    constructor() {
        this.queue = []
    }

    popFront() {
        if (!this.queue.length) return null
        return this.queue.shift()
    }

    front() {
        return this.queue[0]
    }

    pushBack(item) {
        this.queue.push(item)
    }

}

