    get isStarted() {
        return this._isStarted;
    }

    set isStarted(value) {
        this._isStarted = toBool(value);
        let title = this._control.querySelector("#title");
        let buttonStart = this._control.querySelector("#start");
        title.setAttribute("style", `background: ${this.isStarted ? "red" : "grey"};`);
        buttonStart.setAttribute("style", `background: ${this.isStarted ? "red" : "grey"};`);
    }

    get speed() {
        return this._speed;
    }

    set speed(value) {
        this._speed = value;
    }

    get frameFrequency() {
        return this._frameFrequency;
    }

    set frameFrequency(value) {
        this._frameFrequency = value;
    }

    get step() {
        return this._step;
    }

    set step(value) {
        this._step = value;
    }

    get title() {
        return this._title ? this._title : this.getAttribute("elname");
    }

    set title(value) {
        this._title = value;
    }

    get dragable() {
        return this._dragable;
    }
    set dragable(value) {
        this._dragable = value;
        if (this._dragable) {
            if (!this._dnd && this._popup) {
                if (this._showtitle) {
                    this._dnd = new DragElement(this._popup, this._title, { controlPosition: this._boundsrestricted, scale: this._scale || 1 });
                } else {
                    this._dnd = new DragElement(this._popup, this._popup, { controlPosition: this._boundsrestricted, scale: this._scale || 1 });
                }
            }
        }
    }

    get isControlVisible() {
        return this._isControlVisible;
    }

    set isControlVisible(value) {
        this._isControlVisible = value;
    }

    get startTimer() {
        return this._startTimer;
    }

    set startTimer(value) {
        this._startTimer = value;
    }


    get endTimer() {
        return this._endTimer;
    }

    set endTimer(value) {
        this._endTimer = value;
    }


    get nowTimer() {
        console.log(this._nowTimer, this.intervalId)
        return this._nowTimer;
    }

    set nowTimer(value) {
        if (value > this.endTimer) {
            if (this.intervalId) {
                clearInterval(this.intervalId);
                return;
            }
        }
        this._nowTimer = value;
        let range = this._control.querySelector("#customrange");
        range.setAttribute("value", `${this.nowTimer}`);
    }

