    setScaleMax(e, row) {
        const type = row.getData()._type;
        if (type === "custom") return;
        if (
            $pm.hasPermissions &&
            !$pm.checkAllow($pm.getEntryFromElement(this, "TrendChangePens"))
        )
            return;
        const { maxy, title, isMain, autoscale, yformat} = JSON.parse(row.getData().scalemax)
        if (autoscale) return
        const { miny } = JSON.parse(row.getData().scalemin)
        const maxdecimalplaces = this.getMaxdecimalplaces(yformat)
        const inputNum = new Inputs(this._in);
        const html = `<style>${popupCss}</style>${(title && !isMain) ? `<div class="tooltip-wrap"><div style="width: 100%;text-align: center;color: #1E90FF;">${i18next.t('legend_scale_no_use')}</div><div class="tooltip">${i18next.t('legend_scale_no_use_tooltip')}</div></div>` : ''}
            <p style="text-align: center; width: 100%; margin: 7px 0;">Max</p>`
        inputNum.inputBoxNumber(
            null,
            html,
            maxy,
            (v) => {
                const value = Number(v);
                if (!isNaN(value) && maxy !== value) {
                    if ($pm.hasPermissions) {
                        const options = {
                            cancel: () => { },
                            customText: `${this.elname} Изменение шкалы пера ${this._trendControl.pens[row.getIndex()].name
                                }: ${this._trendControl.pens[row.getIndex()].miny
                                }-${value}`,
                        };
                        $pm.resolveControl(
                            this,
                            "TrendChangePens",
                            () => {
                                this._trendControl.pens[row.getIndex()].maxy =
                                    value;
                                this._trendControl.saveState();
                            },
                            options
                        );
                    } else {
                        this._trendControl.pens[row.getIndex()].maxy = value;
                        this._trendControl.saveState();
                    }
                    if(isMain){
                        this._trendControl.trendGroups.reinit();
                    }
                }
            },
            {
                toBody: true,
                alignToElement: true,
                element: e.target,
                showFocus: true,
                min: miny,
                max: Infinity,
                maxdecimalplaces,
                zIndex: 11000000,
            }
        );
        const numericElem = inputNum._PopupDiv.querySelector('ms-numericupdown')
        this.restyleNumericUpDown(numericElem)
    }

