    getMaxdecimalplaces(format){
        const startsWithAllowedCharacter = ["f", "{f"].some(x =>
            format.startsWith(x)
        );
        if(startsWithAllowedCharacter){
            const cleanedformat = format.replace(/[{}]/g, '');
            return cleanedformat.match(/\d+/)[0];
        } else {
            return 3
        }
    }

