    connectedCallback() {
        this.table = new Tabulator(this._main, {
            autoResize: true,
            layout: "fitData",
            height: "100%", // Высота таблицы
            layoutColumnsOnNewData: false,
            virtualDom: true,
            pagination: false,
            columns: this.columns,
            // movableColumns: true,
            headerSortTristate: true,
            resizableRows:true,
            columnDefaults:{
                resizable:true,
            },
        });
        this.table.on("columnResized", (column) => {
            this._saveState();
            if (!column.getDefinition().frozen) return;
            let width = 0;
            for (const col of column.getTable().getColumns()) {
                if (
                    col.getField() !== column.getField() &&
                    col.getDefinition().frozen
                ) {
                    width += col._column.width;
                }
            }
            if (width + column._column.getWidth() > this.width - 10) {
                column._column.setWidth(this.width - 11 - width);
            }
        });
        this.table.on("rowClick", (e, row) => {
            const index = row.getIndex();
            this._trendControl.selectPen(index);
        });
        this.table.on("cellClick", (e, cell) => {
            switch (cell.getField()) {
                case "graph":
                    this.setGraph(e, cell.getRow());
                    break;
                default:
                    break;
            }
        })
        this.table.on("cellDblClick", (e, cell) => {
            switch (cell.getField()) {
                case "scalemax":
                    this.setScaleMax(e, cell.getRow());
                    break;
                case "scalemin":
                    this.setScaleMin(e, cell.getRow());
                    break;
                default:
                    break;
            }
        })
        this.table.on("tableBuilt", (data) => {
            this.tableBody = this.shadowRoot.querySelector('.tabulator-table')
            this.tableHeader = this.shadowRoot.querySelector('.tabulator-header')
            this.tableBody = this.shadowRoot.querySelector('.tabulator-table')
            this._shAll = this._main.querySelector(".tabulator-col");
            const showclolumns = [{name: "showpen", nameColumn: "graph"}, {name: "showname", nameColumn: "name"}, {name: "showsource", nameColumn: "source"},
                {name: "showgroup", nameColumn: "group"}, {name: "showvalue", nameColumn: "value"}, {name: "showavarage", nameColumn: "avarage"},
                {name: "showcomment", nameColumn: "comment"}, {name: "showunit", nameColumn: "units"},  {name: "showlastvaluetime", nameColumn: "lasttime"},
                {name: "showquality", nameColumn: "isbad"}, {name: "showmin", nameColumn: "scalemin"}, {name: "showmax", nameColumn: "scalemax"},
                {name: "shownau", nameColumn: "lolo"}, {name: "shownpu", nameColumn: "lo"}, {name: "showvpu", nameColumn: "hi"},
                {name: "showvau", nameColumn: "hihi"}, {name: "showstartvalue", nameColumn: "start"}, {name: "showminvalue", nameColumn: "min"},
                {name: "showmaxvalue", nameColumn: "max"}, {name: "showlastvalue", nameColumn: "end"}] 
            this.tableInited = true
            showclolumns.forEach((item) => {
                const value = this[`_initial${item.name}`];
                if (value === false) this.table.hideColumn(item.nameColumn)
                else this.table.showColumn(item.nameColumn)
            })
            this.initMenu()
            if(this.columnfontcolor) this.columnfontcolor = this._columnfontcolor;
            if(this.setcolumnitalic) this.setcolumnitalic = this._setcolumnitalic;
            if(this.setcolumnbolt) this.setcolumnbolt = this._setcolumnbolt;
            if(this.setcolumnunderline) this.setcolumnunderline = this._setcolumnunderline;
                // columnfontsize columnalignhorizontal
            if(this.columnalignhorizontal) this.columnalignhorizontal = this._columnalignhorizontal;
            if(this.columnfontsize) this.columnfontsize = this._columnfontsize;

        });
        this.connectedTimeout = setTimeout(() => {
            this.table?.redraw(true);
        }, 100);
    }

    disconnectedCallback() {
        this._saveState();
        delete this.__reciver;
        this.table.destroy();
        this.menu.destroy();
        this.menu = null;
        clearTimeout(this.connectedTimeout);
        delete this.table;

        super.disconnectedCallback();
    }

    _saveState() {
        const save = [];
        if (this.table && this.table.getColumnLayout) {
            const col = this.table.getColumns();
            col.forEach((el) => {
                save.push({ width: el._column.width });
            });
            let headers = Number(
                /.\d/.exec(
                    this.table.element.querySelector('[role="columnheader"]')
                        .style.height
                )
            );
            const s = { col: save, header: headers };
            this.saveItemState({ colState: s });
        }
    }
    _loadState() {
        try {
            this.originPath = this.getOriginPath();
            let storedState = $ss.getItemState(this.originPath);
            if (storedState) {
                const save = storedState.colState || [];
                for (let i = 0; i < save.col.length; i++) {
                    this.columns[i].width = save.col[i].width;
                }
                this.stateLoaded = true
            }
        } catch (error) { }
    }

