    get columnalignhorizontal() {
        return this._columnalignhorizontal
    }
    set columnalignhorizontal(v) {
        this._columnalignhorizontal = v
        if(!this.tableInited) return
        if (v === '0') {
            const headerCols = this.shadowRoot.querySelectorAll('.tabulator-col')
            headerCols.forEach(col => col.style.textAlign = 'left')
            this.tableBody.style.textAlign = "left"
        }
        if (v === '2') {
            const headerCols = this.shadowRoot.querySelectorAll('.tabulator-col')
            headerCols.forEach(col => col.style.textAlign = 'right')
            this.tableBody.style.textAlign = "right"
        }
        if (v === "1") {
            const headerCols = this.shadowRoot.querySelectorAll('.tabulator-col')
            headerCols.forEach(col => col.style.textAlign = 'center')
            this.tableBody.style.textAlign = "center"
        }
    }

    get columnwidth() {
        return this._columnwidth
    }

    set columnwidth(v) {
        const value = parseInt(v)
        this._columnwidth = value
        if(!this.stateLoaded){
            this.columns.forEach((col) => {
                col.width = value
            })
        }
    }

    get columnfontsize() {
        return this._columnfontsize
    }

    set columnfontsize(v) {
        this._columnfontsize = v
        if(!this.tableInited) return
        this.tableBody.style.fontSize = v + "px"
        this.tableHeader.style.fontSize = v + "px"
    }

    get columnfontcolor() {
        return this._columnfontcolor
    }

    set columnfontcolor(v) {
        this._columnfontcolor = v
        if(!this.tableInited) return
        v = this.tryToGetUserColor(v);
        this.tableBody.style.color = v
        this.tableHeader.style.color = v
    }

    get setcolumnitalic() {
        return this._setcolumnitalic
    }

    set setcolumnitalic(v) {
        const value = this._toBool(v)
        this._setcolumnitalic = value
        if (!value || !this.tableInited) return
        this.tableBody.style.fontStyle = 'italic'
        this.tableHeader.style.fontStyle = 'italic'
    }

    get setcolumnbolt() {
        return this._setcolumnbolt
    }

    set setcolumnbolt(v) {
        const value = this._toBool(v)
        this._setcolumnbolt = value
        if (!value || !this.tableInited) return
        this.tableHeader.style.fontWeight = 700
        this.tableBody.style.fontWeight = 700
    }

