}

.btn {
    margin: 2px;
}

    .btn:hover {
        background-color: rgba(44, 111, 215, 0.04);
    }

    .btn.active {
        background-color: rgba(44, 111, 215, 0.32);
    }

button.ack,
.windowIdLinkBtn {
    background: linear-gradient(180deg, rgba(44, 111, 215, 1) 0%, rgba(52, 90, 164, 1) 100%);
    border: 0.5px solid rgba(52, 90, 164, 1);
    box-sizing: border-box;
