    font-family: sans-serif;
    font-size: 12px;
    padding: 0 6px 2px 6px;
}

    button.ack:disabled,
    .windowIdLinkBtn:disabled {
        background: linear-gradient(180deg, rgba(158, 158, 158, 1) 0%, rgba(128, 128, 128, 1) 100%);
        border: 0.5px solid rgba(158, 158, 158, 1);
        color: rgba(199, 199, 199, 1);
        box-shadow: unset;
