        background: linear-gradient(180deg, rgba(158, 158, 158, 1) 0%, rgba(128, 128, 128, 1) 100%);
    }

th {
    user-select: none;
}

    th div {
        pointer-events: none;
    }

    th > div {
        display: flex;
        align-items: center;
        justify-content: center;
    }

        th > div > div {
            overflow: hidden;
            text-overflow: ellipsis;
            white-space: nowrap;
        }

        th > div > .btn {
            font-size: medium;
            pointer-events: auto;
        }

            th > div > .btn.disable {
                color: lightgray;
                pointer-events: none;
            }

.bookmarksList {
    user-select: none;
    display: flex;
    margin: 3px;
    cursor: pointer;
    text-align: start;
}

    .bookmarksList:hover {
        background-color: rgba(44, 111, 215, 0.32);
    }

    .bookmarksList > button {
        visibility: hidden;
    }

    .bookmarksList:hover > button {
        visibility: visible;
    }

thead {
    position: relative;
    z-index: 1;
}

@keyframes flash {
    0% {
        background-color: transparent
    }

    50% {
        background-color: var(--bg-color)
    }

    100% {
        background-color: transparent
    }
}

.hidden {
    visibility: hidden;
